47	// 计算有序批次的叶子层。严格按 paths 下标顺序：不排序、不去重。
48	// 任一文件失败立即返回该错误，不读取也不使用其后的任何文件。
49	std::string leaf_level(const std::vector<std::filesystem::path>& paths,
50	                       std::vector<Digest>& level) {
51	    level.clear();
52	    level.reserve(paths.size());
53	    for (const std::filesystem::path& path : paths) {
54	        FileHashResult leaf = leaf_file(path);
55	        if (!leaf.ok()) {
56	            return std::move(leaf.error);
57	        }
58	        level.push_back(leaf.digest);
59	    }
60	    return {};
61	}
