63	// 批次合并规则（root 与 prove 共用的唯一一份实现）：对当前层做一次相邻
64	// 配对——相邻节点按先左后右两两用 merkle_parent 合并；若该层节点数为
65	// 奇数，最后一个没有伙伴的节点摘要原样进入上一层（不复制、不补零）。
66	// 输入层不被修改，返回合并后的上一层；输入只有一个节点时返回的层同样
67	// 只有该节点本身。
68	std::vector<Digest> combine_level(const std::vector<Digest>& level) {
69	    std::vector<Digest> next;
70	    const bool odd = (level.size() % 2) != 0;
71	    next.reserve(level.size() / 2 + (odd ? 1 : 0));
72	    for (std::size_t i = 0; i + 1 < level.size(); i += 2) {
73	        next.push_back(merkle_parent(level[i], level[i + 1]));
74	    }
75	    if (odd) {
76	        next.push_back(level.back());
77	    }
78	    return next;
79	}
