228	    // 扫描一个 JSON 数字的语法区间并在必须为无符号整数时拒绝非整数写法。
229	    // must_be_uint 为真时：不得有符号/小数/指数；成功时 [start,pos) 即
230	    // 一段 0..2^64-1 的十进制数字（是否超界由 read_uint64 用 from_chars
231	    // 判定）。返回 [start,pos) 长度便于调用方取出数字串。
232	    bool scan_number(bool must_be_uint, std::size_t& start, std::size_t& end) {
233	        start = pos;
234	        if (!eof() && peek() == '-') {
235	            ++pos;
236	            if (must_be_uint) {
237	                return fail("negative integer is not allowed");
238	            }
239	        }
240	        // 整数部分：JSON 不允许前导 0（"0" 之后不能再跟数字）。
241	        if (eof() || peek() < '0' || peek() > '9') {
242	            return fail("invalid JSON number");
243	        }
244	        if (peek() == '0') {
245	            ++pos;
246	            if (!eof() && peek() >= '0' && peek() <= '9') {
247	                return fail("leading zeros are not allowed in JSON numbers");
248	            }
249	        } else {
250	            while (!eof() && peek() >= '0' && peek() <= '9') {
251	                ++pos;
252	            }
253	        }
254	        bool fraction_or_exponent = false;
255	        if (!eof() && peek() == '.') {
256	            fraction_or_exponent = true;
257	            ++pos;
258	            if (eof() || peek() < '0' || peek() > '9') {
259	                return fail("invalid JSON fraction");
260	            }
261	            while (!eof() && peek() >= '0' && peek() <= '9') {
262	                ++pos;
263	            }
264	        }
265	        if (!eof() && (peek() == 'e' || peek() == 'E')) {
266	            fraction_or_exponent = true;
267	            ++pos;
268	            if (!eof() && (peek() == '+' || peek() == '-')) {
269	                ++pos;
270	            }
271	            if (eof() || peek() < '0' || peek() > '9') {
272	                return fail("invalid JSON exponent");
273	            }
274	            while (!eof() && peek() >= '0' && peek() <= '9') {
275	                ++pos;
276	            }
277	        }
278	        if (must_be_uint && fraction_or_exponent) {
279	            // 1.0、1e0 这类写法在 JSON 里是数字，但不是“JSON 整数”，
280	            // leaf_count/leaf_index/version 必须准确保留整数值。
281	            return fail("only JSON integers are accepted for this field");
282	        }
283	        end = pos;
284	        return true;
285	    }
286	
287	    // 读取字段值位置上的无符号 64 位 JSON 整数。
288	    bool read_uint64(std::uint64_t& out, std::string_view field) {
289	        ws();
290	        if (eof()) {
291	            return fail(std::string("missing value for field \"") +
292	                        std::string(field) + "\"");
293	        }
294	        const char c = peek();
295	        if (c == '"') {
296	            return fail(std::string("field \"") + std::string(field) +
297	                        "\" must be a JSON integer, got a string");
298	        }
299	        if (c == 't' || c == 'f' || c == 'n') {
300	            return fail(std::string("field \"") + std::string(field) +
301	                        "\" must be a JSON integer, got a boolean or null");
302	        }
303	        if (c == '{' || c == '[') {
304	            return fail(std::string("field \"") + std::string(field) +
305	                        "\" must be a JSON integer, got a container");
306	        }
307	        if (c != '-' && (c < '0' || c > '9')) {
308	            return fail(std::string("field \"") + std::string(field) +
309	                        "\" has an invalid value");
310	        }
311	        std::size_t start = 0;
312	        std::size_t end = 0;
313	        if (!scan_number(/*must_be_uint=*/true, start, end)) {
314	            return false;
315	        }
316	        const std::string_view digits(text.data() + start, end - start);
317	        const auto res = std::from_chars(
318	            digits.data(), digits.data() + digits.size(), out);
319	        if (res.ec != std::errc{} ||
320	            res.ptr != digits.data() + digits.size()) {
321	            return fail(std::string("field \"") + std::string(field) +
322	                        "\" integer is out of unsigned 64-bit range");
323	        }
324	        return true;
325	    }
326	
327	    // 读取字段值位置上的 JSON 字符串。
328	    bool read_string_value(std::string& out, std::string_view field) {
329	        ws();
330	        if (eof()) {
331	            return fail(std::string("missing value for field \"") +
332	                        std::string(field) + "\"");
333	        }
334	        const char c = peek();
335	        if (c != '"') {
336	            return fail(std::string("field \"") + std::string(field) +
337	                        "\" must be a JSON string");
338	        }
339	        return read_string(out);
340	    }
341	};
342	
343	// 把恰好 64 个小写十六进制字符还原为 32 字节摘要。长度不符、含非十六
344	// 进制字符或使用大写字符都明确失败：不截断、不替换损坏内容。
345	bool parse_digest_hex(const std::string& hex, Digest& out) {
346	    if (hex.size() != 64) {
347	        return false;
348	    }
349	    auto nibble = [](char c, unsigned int& v) -> bool {
350	        if (c >= '0' && c <= '9') {
351	            v = static_cast<unsigned int>(c - '0');
352	            return true;
353	        }
354	        // 只接受小写：A-F 等大写字符在此失败，而不是被当作同一摘要。
355	        if (c >= 'a' && c <= 'f') {
356	            v = static_cast<unsigned int>(c - 'a' + 10);
357	            return true;
358	        }
359	        return false;
360	    };
361	    for (std::size_t i = 0; i < 32; ++i) {
362	        unsigned int hi = 0;
363	        unsigned int lo = 0;
364	        if (!nibble(hex[2 * i], hi) || !nibble(hex[2 * i + 1], lo)) {
365	            return false;
366	        }
367	        out[i] = static_cast<std::uint8_t>((hi << 4) | lo);
368	    }
369	    return true;
370	}
371	
372	// 读取字段值位置上的摘要字符串：恰好 64 个小写十六进制字符。
373	bool read_digest_value(JsonParser& p, Digest& out, std::string_view field) {
374	    std::string raw;
375	    if (!p.read_string_value(raw, field)) {
376	        return false;
377	    }
378	    if (!parse_digest_hex(raw, out)) {
379	        return p.fail(std::string("field \"") + std::string(field) +
380	                      "\" must be exactly 64 lowercase hexadecimal characters "
381	                      "decoding to 32 bytes");
382	    }
383	    return true;
384	}
385	
386	// 解析一个兄弟对象：只允许 side 与 digest 两个字段，均必填、不得重复、
387	// 不得出现其他字段。调用时 p 已停在起始 '{' 之后的位置。
388	bool parse_sibling_object(JsonParser& p, MerkleSibling& sibling) {
389	    bool have_side = false;
390	    bool have_digest = false;
391	    p.ws();
392	    if (!p.eof() && p.peek() == '}') {
393	        ++p.pos;
394	        return p.fail("a siblings entry must contain \"side\" and \"digest\"");
395	    }
396	    while (true) {
397	        p.ws();
398	        if (p.eof() || p.peek() != '"') {
399	            return p.fail("expected string key in sibling object");
400	        }
401	        std::string key;
402	        if (!p.read_string(key)) {
403	            return false;
404	        }
405	        p.ws();
406	        if (p.eof() || p.peek() != ':') {
407	            return p.fail("expected ':' after sibling object key \"" + key +
408	                          "\"");
409	        }
410	        ++p.pos;
411	
412	        if (key == "side") {
413	            if (have_side) {
414	                return p.fail("duplicate field \"side\" in a siblings entry");
415	            }
416	            std::string side;
417	            if (!p.read_string_value(side, "side")) {
418	                return false;
419	            }
420	            if (side == "left") {
421	                sibling.side = MerkleSibling::Side::left;
422	            } else if (side == "right") {
423	                sibling.side = MerkleSibling::Side::right;
424	            } else {
425	                return p.fail("sibling side must be \"left\" or \"right\"");
426	            }
427	            have_side = true;
428	        } else if (key == "digest") {
429	            if (have_digest) {
430	                return p.fail("duplicate field \"digest\" in a siblings entry");
431	            }
432	            if (!read_digest_value(p, sibling.digest, "digest")) {
433	                return false;
434	            }
435	            have_digest = true;
436	        } else {
437	            return p.fail("undefined field \"" + key +
438	                          "\" in a siblings entry (only \"side\" and "
439	                          "\"digest\" are allowed)");
440	        }
441	
442	        p.ws();
443	        if (p.eof()) {
444	            return p.fail("unterminated sibling object");
445	        }
446	        if (p.peek() == '}') {
447	            ++p.pos;
448	            break;
449	        }
450	        if (p.peek() != ',') {
451	            return p.fail("expected ',' or '}' in sibling object");
452	        }
453	        ++p.pos;
454	    }
455	    if (!have_side || !have_digest) {
456	        return p.fail("a siblings entry must contain both \"side\" and "
457	                      "\"digest\"");
458	    }
459	    return true;
460	}
461	
462	// 解析 siblings 数组：顺序、方向与摘要严格按输入保留，不排序、不去重、
463	// 不补记录。调用时 p 已确认当前字符为 '['。
464	bool parse_siblings_array(JsonParser& p,
465	                          std::vector<MerkleSibling>& siblings) {
466	    ++p.pos;  // 跳过 '['
467	    p.ws();
468	    if (!p.eof() && p.peek() == ']') {
469	        ++p.pos;
470	        return true;  // 单文件证明的空兄弟数组。
471	    }
472	    while (true) {
473	        p.ws();
474	        if (p.eof()) {
475	            return p.fail("unterminated siblings array");
476	        }
477	        if (p.peek() != '{') {
478	            return p.fail("each siblings entry must be a JSON object");
479	        }
480	        ++p.pos;  // 跳过 '{'
481	        MerkleSibling& sibling = siblings.emplace_back();
482	        if (!parse_sibling_object(p, sibling)) {
483	            return false;
484	        }
485	        p.ws();
486	        if (p.eof()) {
487	            return p.fail("unterminated siblings array");
488	        }
489	        if (p.peek() == ']') {
490	            ++p.pos;
491	            return true;
492	        }
493	        if (p.peek() != ',') {
494	            return p.fail("expected ',' or ']' in siblings array");
495	        }
496	        ++p.pos;
497	    }
498	}
