577	MerkleVerifyResult merkle_verify_proof(const MerkleProof& proof,
578	                                       const Digest& trusted_root,
579	                                       const Digest& content_leaf) {
580	    MerkleVerifyResult result;
581	
582	    // 空批次没有任何成员；位置必须从 0 开始并落在批次内。
583	    if (proof.leaf_count == 0) {
584	        result.error =
585	            "proof rejected: empty batch (leaf_count is 0) has no members";
586	        return result;
587	    }
588	    if (proof.leaf_index >= proof.leaf_count) {
589	        result.error =
590	            "proof rejected: leaf_index " +
591	            std::to_string(proof.leaf_index) + " is out of range for leaf_count " +
592	            std::to_string(proof.leaf_count);
593	        return result;
594	    }
595	
596	    // 条件 1：待验证内容的叶子摘要必须与证明中的叶子完全一致。
597	    // content_leaf 按叶子规则带单个 0x00 前缀；普通文件摘要（无此前缀）
598	    // 不可能与真实叶子相等，不能借此通过。
599	    if (content_leaf != proof.leaf) {
600	        result.error =
601	            "proof rejected: supplied content leaf digest does not match the "
602	            "leaf digest in the proof";
603	        return result;
604	    }
605	
606	    // 条件 4 + 条件 3 的折叠：兄弟的方向、数量与从叶子向根的次序必须严格
607	    // 符合 (leaf_count, leaf_index) 描述的位置；在逐层核对的同时按
608	    // SHA-256(0x01||left||right) 折叠。不能只在最后比对摘要——结构不符
609	    // （侧向错、缺项、多项、次序错）即使凑出相等摘要也必须拒绝。
610	    //
611	    // 各层节点数只做纯 uint64 模拟，绝不按 leaf_count 分配内存；上一层
612	    // 大小为 ceil(n/2)，写成 n - n/2 —— n 为奇数时 (n+1)/2 在
613	    // n=UINT64_MAX 处会回绕，n - n/2 不会。层数关于 n 有界（至多 64 层），
614	    // 因此最大可表示的合法计数也立即得到确定结果。
615	    std::uint64_t level_size = proof.leaf_count;
616	    std::uint64_t pos = proof.leaf_index;
617	    std::uint64_t tree_level = 0;  // 叶子之上第一层为 0，仅用于错误信息
618	    std::size_t consumed = 0;
619	    Digest node = content_leaf;
620	
621	    while (level_size > 1) {
622	        // 与 merkle_proof_file 的记录规则完全一致：偶数位置且该位置是
623	        // 奇数层末节点时，节点原样提升，本层没有兄弟、不消费记录；
624	        // 偶数且右侧仍有伙伴 -> 必须有 right 兄弟；奇数位置 -> 必须有
625	        // left 兄弟（pos>=1，左侧伙伴必然存在）。
626	        // 写成 pos == level_size - 1 而非 pos + 1 >= level_size：
627	        // level_size > 1 保证减法安全，而 pos+1 在 pos=UINT64_MAX 时会
628	        // 无符号回绕成 0，恰好把“末节点提升”误判成“右侧有兄弟”。
629	        const bool promoted_without_sibling =
630	            (pos % 2 == 0) && (pos == level_size - 1);
631	
632	        if (!promoted_without_sibling) {
633	            if (consumed >= proof.siblings.size()) {
634	                result.error =
635	                    "proof rejected: missing required sibling at tree level " +
636	                    std::to_string(tree_level) + " for leaf_index " +
637	                    std::to_string(proof.leaf_index) + " of leaf_count " +
638	                    std::to_string(proof.leaf_count);
639	                return result;
640	            }
641	
642	            const MerkleSibling& sibling = proof.siblings[consumed];
643	
644	            // side 只能是 left 或 right：证明结构可能由调用方自行构造，
645	            // 非法枚举值也必须明确拒绝，不能落入任一分支碰运气。
646	            bool sibling_on_right;
647	            if (sibling.side == MerkleSibling::Side::right) {
648	                sibling_on_right = true;
649	            } else if (sibling.side == MerkleSibling::Side::left) {
650	                sibling_on_right = false;
651	            } else {
652	                result.error =
653	                    "proof rejected: sibling at tree level " +
654	                    std::to_string(tree_level) +
655	                    " has an invalid side (only left or right is allowed)";
656	                return result;
657	            }
658	
659	            const bool expected_on_right = (pos % 2 == 0);
660	            if (sibling_on_right != expected_on_right) {
661	                result.error =
662	                    "proof rejected: sibling at tree level " +
663	                    std::to_string(tree_level) + " is on the " +
664	                    (sibling_on_right ? "right" : "left") +
665	                    " side, but the position in the batch requires it on the " +
666	                    (expected_on_right ? "right" : "left");
667	                return result;
668	            }
669	
670	            node = sibling_on_right
671	                       ? merkle_parent(node, sibling.digest)
672	                       : merkle_parent(sibling.digest, node);
673	            ++consumed;
674	        }
675	        // 原样提升或正常配对后，被选位置在上一层的下标都是 floor(pos/2)；
676	        // pos 始终小于 level_size，不会触及 UINT64_MAX 回绕。
677	        pos /= 2;
678	        ++tree_level;
679	        const std::uint64_t half = level_size / 2;
680	        level_size -= half;  // ceil(level_size/2)，无回绕。
681	    }
682	
683	    // 到达根后不得还有多余兄弟。
684	    if (consumed != proof.siblings.size()) {
685	        result.error =
686	            "proof rejected: proof carries " +
687	            std::to_string(proof.siblings.size()) +
688	            " sibling(s), but the batch position requires exactly " +
689	            std::to_string(consumed);
690	        return result;
691	    }
692	
693	    // 条件 2：信任锚只来自调用方单独传入的可信根；证明自报的 root 不能
694	    // 充当信任依据——属于另一批次的证明即使内部自洽也在此被拒。
695	    if (proof.root != trusted_root) {
696	        result.error =
697	            "proof rejected: root claimed by the proof does not match the "
698	            "trusted batch root";
699	        return result;
700	    }
701	
702	    // 条件 3：兄弟必须真的把内容叶子折叠到可信根（防止 root 字段被改成
703	    // 可信根、但兄弟链与叶子并不相容的证明）。
704	    if (node != trusted_root) {
705	        result.error =
706	            "proof rejected: the supplied siblings do not combine the content "
707	            "leaf into the trusted batch root";
708	        return result;
709	    }
710	
711	    result.valid = true;
712	    return result;
713	}
714	
715	MerkleProofParseResult merkle_proof_from_json(std::string_view text) {
716	    MerkleProofParseResult result;
717	
718	    // 全程写入本地 proof：只有文本完整通过后才移入返回值，任何失败都不
719	    // 留下可用的部分证明（返回对象保持默认构造）。
720	    MerkleProof proof;
721	    JsonParser p;
722	    p.text = text;
723	
724	    enum FieldBit : unsigned {
725	        kVersion = 1u << 0,
726	        kRoot = 1u << 1,
727	        kLeafCount = 1u << 2,
728	        kLeafIndex = 1u << 3,
729	        kLeaf = 1u << 4,
730	        kSiblings = 1u << 5,
731	    };
732	    constexpr unsigned kAllFields = kVersion | kRoot | kLeafCount |
733	                                    kLeafIndex | kLeaf | kSiblings;
734	    unsigned seen = 0;
735	
736	    p.ws();
737	    if (p.eof()) {
738	        result.error =
739	            "proof text rejected: input is empty or whitespace only "
740	            "(expected a version 1 proof JSON object)";
741	        return result;
742	    }
743	    if (p.peek() != '{') {
744	        result.error =
745	            "proof text rejected: top-level value must be a single JSON object";
746	        return result;
747	    }
748	    ++p.pos;
749	    p.ws();
750	
751	    // 空对象（"{}"）不进入字段循环，直接落到后面的必填字段检查。
752	    if (!p.eof() && p.peek() == '}') {
753	        ++p.pos;
754	    } else {
755	        while (p.error.empty()) {
756	        p.ws();
757	        if (p.eof() || p.peek() != '"') {
758	            p.fail("expected a string field name in proof object");
759	            break;
760	        }
761	        std::string key;
762	        if (!p.read_string(key)) {
763	            break;
764	        }
765	        p.ws();
766	        if (p.eof() || p.peek() != ':') {
767	            p.fail("expected ':' after proof object field \"" + key + "\"");
768	            break;
769	        }
770	        ++p.pos;
771	
772	        unsigned bit = 0;
773	        if (key == "version") {
774	            bit = kVersion;
775	        } else if (key == "root") {
776	            bit = kRoot;
777	        } else if (key == "leaf_count") {
778	            bit = kLeafCount;
779	        } else if (key == "leaf_index") {
780	            bit = kLeafIndex;
781	        } else if (key == "leaf") {
782	            bit = kLeaf;
783	        } else if (key == "siblings") {
784	            bit = kSiblings;
785	        } else {
786	            p.fail("undefined field \"" + key + "\" in proof object (version 1 "
787	                   "defines only version, root, leaf_count, leaf_index, leaf "
788	                   "and siblings)");
789	            break;
790	        }
791	        if (seen & bit) {
792	            p.fail("duplicate field \"" + key + "\" in proof object");
793	            break;
794	        }
795	
796	        if (bit == kVersion) {
797	            std::uint64_t version = 0;
798	            if (!p.read_uint64(version, "version")) {
799	                break;
800	            }
801	            if (version != 1) {
802	                p.fail("unsupported proof version " +
803	                       std::to_string(version) + " (only version 1 is "
804	                       "supported)");
805	                break;
806	            }
807	        } else if (bit == kRoot) {
808	            if (!read_digest_value(p, proof.root, "root")) {
809	                break;
810	            }
811	        } else if (bit == kLeafCount) {
812	            if (!p.read_uint64(proof.leaf_count, "leaf_count")) {
813	                break;
814	            }
815	        } else if (bit == kLeafIndex) {
816	            if (!p.read_uint64(proof.leaf_index, "leaf_index")) {
817	                break;
818	            }
819	        } else if (bit == kLeaf) {
820	            if (!read_digest_value(p, proof.leaf, "leaf")) {
821	                break;
822	            }
823	        } else {  // kSiblings
824	            p.ws();
825	            if (p.eof() || p.peek() != '[') {
826	                p.fail("field \"siblings\" must be a JSON array");
827	                break;
828	            }
829	            if (!parse_siblings_array(p, proof.siblings)) {
830	                break;
831	            }
832	        }
833	        seen |= bit;
834	
835	        p.ws();
836	        if (p.eof()) {
837	            p.fail("unterminated proof object");
838	            break;
839	        }
840	        if (p.peek() == '}') {
841	            ++p.pos;
842	            break;
843	        }
844	        if (p.peek() != ',') {
845	            p.fail("expected ',' or '}' in proof object");
846	            break;
847	        }
848	        ++p.pos;
849	        // 逗号之后要求另一个字段名；循环回到顶部做该检查。
850	        }
851	    }
852	
853	    if (p.error.empty()) {
854	        // 对象之后除 JSON 空白外不得再有任何内容：不能只取前半段当作成功。
855	        p.ws();
856	        if (!p.eof()) {
857	            p.fail("unexpected trailing content after the proof JSON object");
858	        }
859	    }
860	    if (p.error.empty() && seen != kAllFields) {
861	        std::string missing;
862	        auto add = [&](unsigned b, const char* name) {
863	            if (!(seen & b)) {
864	                if (!missing.empty()) {
865	                    missing += ", ";
866	                }
867	                missing += '"';
868	                missing += name;
869	                missing += '"';
870	            }
871	        };
872	        add(kVersion, "version");
873	        add(kRoot, "root");
874	        add(kLeafCount, "leaf_count");
875	        add(kLeafIndex, "leaf_index");
876	        add(kLeaf, "leaf");
877	        add(kSiblings, "siblings");
878	        p.fail("proof object is missing required field(s): " + missing);
879	    }
880	
881	    if (!p.error.empty()) {
882	        result.error = "proof text rejected: " + p.error;
883	        return result;
884	    }
885	
886	    result.proof = std::move(proof);
887	    return result;
888	}
