1847	void test_large_files() {
1848	    TempArea tmp("large");
1849	    const std::vector<unsigned char> big = fill_a(200000);
1850	    const std::vector<unsigned char> pat = pattern(200000);
1851	    const fs::path f_big = tmp.root / "a200000.bin";
1852	    const fs::path f_pat = tmp.root / "pattern200000.bin";
1853	    write_file(f_big, big);
1854	    write_file(f_pat, pat);
1855	
1856	    check(hex_of(root_of({f_big})) ==
1857	              "0ce74c178a2d90235341a8a2e17539e34aad75dfead1f361b5bec500c1eff93e",
1858	          "single large file leaf (streaming)");
1859	    check(hex_of(root_of({f_big, f_pat})) ==
1860	              "a801ef6c29a4ee3e4e2bc339c7437fe24a2bc10b86571825062a80f6a374daa0",
1861	          "root [big, pattern]");
1862	    check(hex_of(root_of({f_pat, f_big})) ==
1863	              "892596758489f559ec8778ed1d271cd52b18a340926ef47cd16481a432bf2494",
1864	          "root [pattern, big] differs under reversal");
1865	
1866	    // 仅最后一个字节不同：叶子必须随之改变（流式尾部不遗漏）。
1867	    std::vector<unsigned char> tail = big;
1868	    tail.back() = static_cast<unsigned char>('b');
1869	    const fs::path f_tail = tmp.root / "a200000tail.bin";
1870	    write_file(f_tail, tail);
1871	    check(hex_of(root_of({f_tail})) ==
1872	              "e705589769e167619ac6a979e5e06f245ff1ff34a65f34e261b728abc4698a75",
1873	          "large file: changing last byte changes leaf/root");
1874	    check(root_of({f_tail}) != root_of({f_big}),
1875	          "large file: tail change is detected");
1876	}
